// === Tab: user.js ===
function User(x, y, userName, userColor, userSize) {
	this.pos = new p5.Vector(x, y);
	this.name = userName;
	this.color = userColor;
	this.size = userSize;
	this.msg = "";
	this.received = frameCount;

	this.display = function() {
		// Display user as a point.
		stroke(this.color);
		strokeWeight(this.size);
		point(this.pos.x, this.pos.y);

		// Display user's name.
		fill(0)
		noStroke();
		text(this.name, this.pos.x, this.pos.y + this.size * 0.7);

		// Display user's message.
		if (this.msg.length > 0) {
			text(this.msg, this.pos.x, this.pos.y-this.size * 0.5 - 5);
		}
	}

	// Returns True if frameCount exceeds timeout threshold.
	this.isTimedOut = function() {
		return (frameCount - this.received > timeOut);
	}
}

// === Tab: particle.js ===
var gravity = new p5.Vector(0, 0.5);


function Particle(x, y, particleColor) {
	this.pos = new p5.Vector(x, y);

	this.vel = new p5.Vector(0, -1);
	this.vel.rotate(radians(random(-25, 25)));
	this.vel.mult(random(3, 8));

	this.acc = new p5.Vector(0, 0);

	this.color = particleColor;

	this.friction = random(0.75, 1);
	this.airDrag = random(0.95, 1);

	this.moveParticle = function() {
		// Add gravity.
		this.acc.add(gravity);

		// Add air drag.
		this.vel.mult(this.airDrag);

		// Move it.
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.acc.mult(0);

		// Resolve collisions against users.
		for (let user in allUsers) {
			// Check if it's within distance.
			let d = dist(this.pos.x, this.pos.y, allUsers[user].pos.x, allUsers[user].pos.y);
			if (d > allUsers[user].size / 2) {
				continue;
			}

			// Move it out of the user.
			let offset = this.pos.copy();
			offset.sub(allUsers[user].pos);
			offset.normalize();
			offset.mult(allUsers[user].size / 2 - d);
			this.pos.add(offset);

			// Adjust velocity to bounce away.
			let bounce = this.pos.copy();
			bounce.sub(allUsers[user].pos);
			bounce.normalize();
			bounce.mult(this.vel.mag() * this.friction);
			this.vel = bounce;
		}
	}

	this.isOutOfBounds = function() {
		return (this.pos.y > height || this.pos.x < 0 || this.pos.x > width);
	}

	this.display = function() {
		stroke(this.color);
		point(this.pos.x, this.pos.y);
	}
}

