/*
Socket IO particles study

A test to get particles from many users emitting from the sketch's socket.
You can open this sketch in two browser tabs to test it out.

Controls:
	- Move the mouse.
	- Hold the mouse button to spawn particles.

Notes:
	- Particle velocities are created locally and are not sent through the socket. 
	  This makes performance faster but each session will see them behave differently.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

var allUsers = {};
var allParticles = [];

var socket = io.connect(":30000?sketch=510330");
var timeOut = 50;
var localName = "you";

//var yourName = parent.sessionUser.fullname;
var yourName = "";
var yourColor;
var yourSize = 100;
var yourMsg = "";

var tooltip = "".concat(
	"Other users can connect to this sketch and join you.\n", 
	"Drag the mouse to spawn particles and have users interact with it. :D\n", 
	"Type-in to chat.\n\n",
	"Open this up in two browsers if you're feeling lonely.");


function setup() {
	createCanvas(windowWidth, windowHeight);

	textAlign(CENTER);

	yourColor = color(random(255), random(255), random(255));

	// Don't use your user name in this session so you can see yourself in a new browser.
	allUsers[localName] = new User((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), yourName, yourColor, yourSize);

	socket.on("sendUserData", sendUserData);
	socket.on("spawnParticles", spawnParticles);
}


function draw() {
	background(255);

	allUsers[localName].pos.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	allUsers[localName].msg = yourMsg;

	// Send your data over the socket.
	socket.emit(
		"sendUserData", 
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 
		red(window.color(yourColor)), green(window.color(yourColor)), blue(window.color(yourColor)), 100, 
		yourName, yourMsg);

	for (let user in allUsers) {
		// Remove all users who timed out.
		if (user != localName) {
			let hasTimedOut = allUsers[user].isTimedOut();
			if (hasTimedOut) {
				delete allUsers[user];
				continue;
			}
		}

		allUsers[user].display();
	}

	// Sim particles.
	strokeWeight(3);

	for (let i = allParticles.length-1; i > -1; i--) {
		let p = allParticles[i];

		p.moveParticle();
		p.display();

		// Remove if it's out of bounds.
		if (p.isOutOfBounds()) {
			allParticles.splice(i, 1);
		}
	}

	// Display tooltip.
	fill(0);
	noStroke();
	text(tooltip, width/2, 50);
}


function mouseDragged() {
	socket.emit(
		"spawnParticles", 
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), yourSize, 
		red(window.color(yourColor)), green(window.color(yourColor)), blue(window.color(yourColor)));

	spawnParticles(
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), yourSize, 
		red(window.color(yourColor)), green(window.color(yourColor)), blue(window.color(yourColor)));
}


function keyTyped() {
	if (keyCode == ENTER) {
		yourMsg = "";
	} else {
		yourMsg += String.fromCharCode(keyCode);
	}
}


function keyPressed() {
	if (keyCode == BACKSPACE) {
		yourMsg = yourMsg.slice(0, -1);
	};
}


function sendUserData(x, y, r, g, b, s, n, msg) {
	if (allUsers[n] == undefined) {
		allUsers[n] = new User(x, y, n, color(r, g, b), s);
	} else {
		allUsers[n].pos.set(x, y);
		allUsers[n].color = color(r, g, b);
	}

	allUsers[n].msg = msg;
	allUsers[n].received = frameCount;
}


function spawnParticles(x, y, s, r, g, b) {
	let c = color(r, g, b);
	let offset = s * 0.5;

	for (let i = 0; i < 10; i++) {
		allParticles.push(new Particle(x, y - offset, c));
	}
}

